/* ---------------------------- Dashboard --------------------------- */

function Dashboard({ data }) {
  const [stateName, setStateName] = useState("Punjab");
  const [crop, setCrop] = useState("wheat");

  const availableCrops = useMemo(() => {
    const s = data.stateSeries[stateName] || {};
    return data.crops.filter((c) => s[c]);
  }, [stateName, data]);

  useEffect(() => {
    if (availableCrops.length && !availableCrops.includes(crop)) setCrop(availableCrops[0]);
  }, [availableCrops, crop]);

  const series = data.stateSeries[stateName]?.[crop];
  const natSeries = data.national[crop];

  const chartData = useMemo(() => {
    if (!series) return [];
    return data.sy.map((y, i) => ({
      year: y,
      state: series.yield[i],
      national: natSeries.yield[i + (data.sy[0] - data.ny[0])],
    }));
  }, [series, natSeries, data]);

  const districts = useMemo(
    () =>
      data.districts
        .filter((d) => d.s === stateName && d.c[crop] && d.c[crop][1] > 0)
        .map((d) => ({ name: d.d, area: d.c[crop][0], yield: d.c[crop][1], mean: d.c[crop][2], year: d.y }))
        .sort((a, b) => b.yield - a.yield),
    [stateName, crop, data]
  );

  const current = lastVal(series?.yield || []);
  const prev = series ? series.yield.filter(Boolean).slice(-6)[0] : null;
  const delta = current && prev ? ((current - prev) / prev) * 100 : null;
  const growth = series ? cagr(series.yield) : null;
  const natNow = lastVal(natSeries.yield);
  const top = districts[0];

  return (
    <section className="at-section at-wrap">
      <div className="at-hd">
        <div>
          <h2 style={{ fontSize: 30 }}>{cropLabel(crop)} in {stateName}</h2>
          <p className="at-sub" style={{ marginTop: 8 }}>
            Recorded area, production and yield — {CROP_META[crop]?.unitNote}. Latest survey year {top?.year || data.meta.to}.
          </p>
        </div>
      </div>

      <div className="at-card" style={{ marginBottom: 16 }}>
        <div className="at-grid g2">
          <div>
            <label className="at-lab" htmlFor="dash-state">State</label>
            <select id="dash-state" className="at-sel" value={stateName} onChange={(e) => setStateName(e.target.value)}>
              {data.states.map((s) => <option key={s}>{s}</option>)}
            </select>
          </div>
          <div>
            <label className="at-lab" htmlFor="dash-crop">Crop</label>
            <select id="dash-crop" className="at-sel" value={crop} onChange={(e) => setCrop(e.target.value)}>
              {availableCrops.map((c) => (
                <option key={c} value={c}>{CROP_META[c]?.emoji} {cropLabel(c)}</option>
              ))}
            </select>
          </div>
        </div>
      </div>

      {!series ? (
        <div className="at-note">
          <Info size={17} style={{ flex: "none" }} />
          <span>{stateName} has no meaningful {cropLabel(crop).toLowerCase()} area in this dataset. Pick another crop above.</span>
        </div>
      ) : (
        <>
          <div className="at-grid g4" style={{ marginBottom: 16 }}>
            <Kpi icon={Wheat} label="State yield" value={fmt(current)} note="kg per hectare" delta={delta} />
            <Kpi icon={MapPin} label="Area sown" value={fmt(series.area)} note="thousand hectares" />
            <Kpi icon={Scale} label="Production" value={fmt(series.prod)} note="thousand tonnes" />
            <Kpi icon={TrendingUp} label="Growth since 1990" value={growth === null ? "—" : `${growth.toFixed(1)}%`} note="compounded per year" />
          </div>

          <div className="at-card" style={{ marginBottom: 16 }}>
            <h3 style={{ fontSize: 18, marginBottom: 4 }}>{stateName} against the national average</h3>
            <p className="at-sub" style={{ marginBottom: 14 }}>Yield in kg per hectare, 1990 onward.</p>
            <ResponsiveContainer width="100%" height={280}>
              <ComposedChart data={chartData} margin={{ top: 5, right: 8, left: -12, bottom: 0 }}>
                <defs>
                  <linearGradient id="gState" x1="0" y1="0" x2="0" y2="1">
                    <stop offset="0%" stopColor="#2f6b3f" stopOpacity={0.35} />
                    <stop offset="100%" stopColor="#2f6b3f" stopOpacity={0.02} />
                  </linearGradient>
                </defs>
                <CartesianGrid stroke="#e4e9dc" vertical={false} />
                <XAxis dataKey="year" {...chartAxis} minTickGap={24} />
                <YAxis {...chartAxis} width={56} />
                <Tooltip {...tipStyle} formatter={(v, n) => [v ? `${fmt(v)} kg/ha` : "no record", n === "state" ? stateName : "All India"]} />
                <Legend wrapperStyle={{ fontSize: 13 }} formatter={(v) => (v === "state" ? stateName : "All India")} />
                <Area type="monotone" dataKey="state" stroke="#2f6b3f" strokeWidth={2.5} fill="url(#gState)" connectNulls dot={false} />
                <Line type="monotone" dataKey="national" stroke="#a8683a" strokeWidth={2} strokeDasharray="5 4" dot={false} connectNulls />
              </ComposedChart>
            </ResponsiveContainer>
          </div>

          <div className="at-grid g2">
            <div className="at-card">
              <h3 style={{ fontSize: 18, marginBottom: 4 }}>Highest yielding districts</h3>
              <p className="at-sub" style={{ marginBottom: 14 }}>
                {districts.length} districts report {cropLabel(crop).toLowerCase()}. The line marks the national average of {fmt(natNow)} kg/ha.
              </p>
              {districts.length === 0 ? (
                <p className="at-sub">No district-level records for this combination.</p>
              ) : (
                <ResponsiveContainer width="100%" height={Math.min(420, 34 * Math.min(districts.length, 12) + 20)}>
                  <BarChart data={districts.slice(0, 12)} layout="vertical" margin={{ top: 0, right: 16, left: 4, bottom: 0 }}>
                    <CartesianGrid stroke="#e4e9dc" horizontal={false} />
                    <XAxis type="number" {...chartAxis} />
                    <YAxis type="category" dataKey="name" {...chartAxis} width={96} />
                    <Tooltip {...tipStyle} formatter={(v) => [`${fmt(v)} kg/ha`, "Yield"]} />
                    <ReferenceLine x={natNow} stroke="#a8683a" strokeDasharray="4 4" />
                    <Bar dataKey="yield" radius={[0, 5, 5, 0]}>
                      {districts.slice(0, 12).map((d, i) => (
                        <Cell key={i} fill={d.yield >= natNow ? "#2f6b3f" : "#7fb069"} />
                      ))}
                    </Bar>
                  </BarChart>
                </ResponsiveContainer>
              )}
            </div>

            <div className="at-card">
              <h3 style={{ fontSize: 18, marginBottom: 4 }}>District detail</h3>
              <p className="at-sub" style={{ marginBottom: 14 }}>
                Latest year beside the ten-year average, so you can see who had an unusual season.
              </p>
              <div className="at-scroll" style={{ maxHeight: 380, overflowY: "auto" }}>
                <table className="at-tbl">
                  <thead>
                    <tr>
                      <th>District</th><th>Area</th><th>Yield</th><th>10-yr avg</th>
                    </tr>
                  </thead>
                  <tbody>
                    {districts.map((d) => {
                      const diff = d.mean ? ((d.yield - d.mean) / d.mean) * 100 : null;
                      return (
                        <tr key={d.name}>
                          <td>{d.name}</td>
                          <td>{fmt(d.area)}</td>
                          <td style={{ fontWeight: 600 }}>{fmt(d.yield)}</td>
                          <td>
                            {fmt(d.mean)}
                            {diff !== null && (
                              <span className={`at-chip ${diff > 3 ? "up" : diff < -3 ? "down" : "flat"}`} style={{ marginLeft: 7 }}>
                                {diff > 0 ? "+" : ""}{diff.toFixed(0)}%
                              </span>
                            )}
                          </td>
                        </tr>
                      );
                    })}
                  </tbody>
                </table>
              </div>
            </div>
          </div>
        </>
      )}
    </section>
  );
}

/* ----------------------------- Predict ---------------------------- */

const DEFAULT_INPUTS = { n: 100, p: 45, k: 45, ph: 6.5, moisture: 32, rainfall: 900, temp: 27, humidity: 65, ndvi: 0.55, historicalYield: 2500 };

function Predict({ data }) {
  const [stateName, setStateName] = useState("Punjab");
  const [districtName, setDistrictName] = useState("Ludhiana");
  const [crop, setCrop] = useState("wheat");
  const [inputs, setInputs] = useState(DEFAULT_INPUTS);
  const [result, setResult] = useState(null);
  const [running, setRunning] = useState(false);

  const districtsInState = useMemo(
    () => data.districts.filter((d) => d.s === stateName).sort((a, b) => a.d.localeCompare(b.d)),
    [stateName, data]
  );
  const district = districtsInState.find((d) => d.d === districtName) || districtsInState[0];
  const cropsHere = district ? Object.keys(district.c) : [];

  useEffect(() => {
    if (districtsInState.length && !districtsInState.some((d) => d.d === districtName))
      setDistrictName(districtsInState[0].d);
  }, [districtsInState, districtName]);

  useEffect(() => {
    if (cropsHere.length && !cropsHere.includes(crop)) setCrop(cropsHere[0]);
  }, [cropsHere, crop]);

  // Prefill the historical-yield anchor and climate guesses from the record.
  useEffect(() => {
    if (!district || !district.c[crop]) return;
    const m = CROP_META[crop];
    const hist = district.c[crop][2] || district.c[crop][1] || 2000;
    setInputs((p) => ({ ...p, historicalYield: Math.round(hist), n: m.optN, p: m.optP, k: m.optK, ph: m.pH, moisture: m.moist, rainfall: m.rain, temp: m.temp }));
    setResult(null);
  }, [district, crop]);

  const set = useCallback((key) => (v) => { setInputs((p) => ({ ...p, [key]: v })); setResult(null); }, []);

  const run = () => {
    setRunning(true);
    setTimeout(() => {
      setResult({ ...predictYield(crop, inputs), alerts: buildAlerts(crop, inputs), recs: buildRecommendations(crop, inputs), at: new Date() });
      setRunning(false);
    }, 850);
  };

  const maxKg = result ? Math.max(...result.drivers.map((d) => Math.abs(d.kg)), 1) : 1;

  return (
    <section className="at-section at-wrap">
      <div className="at-hd">
        <div>
          <h2 style={{ fontSize: 30 }}>Predict a season</h2>
          <p className="at-sub" style={{ marginTop: 8, maxWidth: "60ch" }}>
            The district's own ten-year average is the starting point. Move the readings to see how far a
            season would push the yield above or below it.
          </p>
        </div>
      </div>

      <div className="at-grid at-split">
        {/* ------- inputs ------- */}
        <div>
          <div className="at-card" style={{ marginBottom: 14 }}>
            <h3 style={{ fontSize: 17, marginBottom: 14 }}>Where and what</h3>
            <div style={{ marginBottom: 14 }}>
              <label className="at-lab" htmlFor="p-state">State</label>
              <select id="p-state" className="at-sel" value={stateName} onChange={(e) => setStateName(e.target.value)}>
                {data.states.map((s) => <option key={s}>{s}</option>)}
              </select>
            </div>
            <div style={{ marginBottom: 14 }}>
              <label className="at-lab" htmlFor="p-dist">District</label>
              <select id="p-dist" className="at-sel" value={district?.d || ""} onChange={(e) => setDistrictName(e.target.value)}>
                {districtsInState.map((d) => <option key={d.d}>{d.d}</option>)}
              </select>
            </div>
            <div>
              <label className="at-lab" htmlFor="p-crop">Crop</label>
              <select id="p-crop" className="at-sel" value={crop} onChange={(e) => setCrop(e.target.value)}>
                {cropsHere.map((c) => <option key={c} value={c}>{CROP_META[c]?.emoji} {cropLabel(c)}</option>)}
              </select>
              {district && district.c[crop] && (
                <div className="at-hint">
                  {fmt(district.c[crop][0])} thousand ha sown · ten-year average {fmt(district.c[crop][2])} kg/ha
                </div>
              )}
            </div>
          </div>

          <div className="at-card" style={{ marginBottom: 14 }}>
            <h3 style={{ fontSize: 17, marginBottom: 14 }}>Soil</h3>
            <Slider label="Nitrogen" icon={FlaskConical} value={inputs.n} onChange={set("n")} min={0} max={300} unit="kg/ha" />
            <Slider label="Phosphorus" icon={FlaskConical} value={inputs.p} onChange={set("p")} min={0} max={150} unit="kg/ha" />
            <Slider label="Potassium" icon={FlaskConical} value={inputs.k} onChange={set("k")} min={0} max={200} unit="kg/ha" />
            <Slider label="Soil pH" icon={Scale} value={inputs.ph} onChange={set("ph")} min={4} max={9.5} step={0.1} hint="Most crops do best between 6 and 7.5." />
            <Slider label="Soil moisture" icon={Droplets} value={inputs.moisture} onChange={set("moisture")} min={5} max={65} unit="%" />
          </div>

          <div className="at-card" style={{ marginBottom: 14 }}>
            <h3 style={{ fontSize: 17, marginBottom: 14 }}>Weather and canopy</h3>
            <Slider label="Seasonal rainfall" icon={CloudRain} value={inputs.rainfall} onChange={set("rainfall")} min={0} max={2600} step={10} unit="mm" />
            <Slider label="Average temperature" icon={Thermometer} value={inputs.temp} onChange={set("temp")} min={8} max={45} unit="°C" />
            <Slider label="Relative humidity" icon={Wind} value={inputs.humidity} onChange={set("humidity")} min={10} max={100} unit="%" />
            <Slider label="NDVI" icon={Leaf} value={inputs.ndvi} onChange={set("ndvi")} min={0.05} max={0.9} step={0.01}
              hint="Satellite greenness. Bare soil sits near 0.1; a dense healthy canopy reaches 0.8." />
            <Slider label="Historical yield" icon={Wheat} value={inputs.historicalYield} onChange={set("historicalYield")} min={200} max={12000} step={50} unit="kg/ha"
              hint="Prefilled from this district's record. It anchors the estimate." />
          </div>

          <div style={{ display: "flex", gap: 10, flexWrap: "wrap" }}>
            <button className="at-btn" onClick={run} disabled={running}>
              {running ? <Loader2 size={17} style={{ animation: "at-spin 1s linear infinite" }} /> : <Wand2 size={17} />}
              {running ? "Working it out…" : "Predict the yield"}
            </button>
            <button className="at-btn ghost" onClick={() => { setInputs(DEFAULT_INPUTS); setResult(null); }}>
              <RefreshCw size={16} /> Reset readings
            </button>
          </div>
        </div>

        {/* ------- output ------- */}
        <div>
          {running && <LoadingPanel label="Scoring the season…" />}

          {!running && !result && (
            <div className="at-card" style={{ textAlign: "center", padding: "56px 24px" }}>
              <div style={{ width: 54, height: 54, borderRadius: 16, background: "#e4f0dc", color: "var(--leaf)", display: "grid", placeItems: "center", margin: "0 auto 16px" }}>
                <Sprout size={26} />
              </div>
              <h3 style={{ fontSize: 20, marginBottom: 8 }}>Nothing predicted yet</h3>
              <p className="at-sub" style={{ maxWidth: "38ch", margin: "0 auto" }}>
                Set the readings on the left, then press <strong>Predict the yield</strong>. The estimate, its risks and the
                driver breakdown appear here.
              </p>
            </div>
          )}

          {!running && result && (
            <>
              <div className="at-card" style={{ marginBottom: 14, background: "var(--field)", color: "#eef3e8", borderColor: "var(--field)" }}>
                <div style={{ fontSize: 13, opacity: 0.8, display: "flex", alignItems: "center", gap: 7 }}>
                  <MapPin size={14} /> {district?.d}, {stateName} · {cropLabel(crop)}
                </div>
                <div className="at-display" style={{ fontSize: 54, marginTop: 10 }}>
                  {fmt(result.predicted)} <span style={{ fontSize: 20, fontWeight: 600, opacity: 0.75 }}>kg/ha</span>
                </div>
                <div style={{ fontSize: 14.5, marginTop: 10, opacity: 0.9 }}>
                  Likely between {fmt(result.low)} and {fmt(result.high)} kg/ha · model confidence {result.confidence}%
                </div>
                <div style={{ display: "flex", gap: 10, marginTop: 16, flexWrap: "wrap" }}>
                  <span className="at-chip" style={{ background: "rgba(255,255,255,.14)", color: "#eef3e8" }}>
                    {result.changePct >= 0 ? <ArrowUpRight size={13} /> : <ArrowDownRight size={13} />}
                    {Math.abs(result.changePct).toFixed(1)}% vs the {fmt(result.base)} kg/ha baseline
                  </span>
                  <span className="at-chip" style={{ background: "rgba(255,255,255,.14)", color: "#eef3e8" }}>
                    {fmt((result.predicted * (district?.c[crop]?.[0] || 0)) / 1000, 1)} thousand t at current area
                  </span>
                </div>
              </div>

              <div className="at-card" style={{ marginBottom: 14 }}>
                <h3 style={{ fontSize: 17, marginBottom: 4 }}>What moved the number</h3>
                <p className="at-sub" style={{ marginBottom: 16 }}>
                  Each bar is that reading's effect on the baseline, in kg/ha. Green adds yield, clay takes it away.
                </p>
                {result.drivers.map((d) => {
                  const pct = (Math.abs(d.kg) / maxKg) * 50;
                  const pos = d.kg >= 0;
                  return (
                    <div className="at-bar-row" key={d.key}>
                      <span title={d.detail}>{d.label}</span>
                      <div className="at-bar-track">
                        <div className="at-bar-mid" style={{ left: "50%" }} />
                        <div className="at-bar-fill"
                          style={{ width: `${pct}%`, left: pos ? "50%" : `${50 - pct}%`, background: pos ? "var(--leaf)" : "var(--clay)" }} />
                      </div>
                      <span style={{ textAlign: "right", fontVariantNumeric: "tabular-nums", fontWeight: 600, color: pos ? "var(--leaf)" : "var(--clay)" }}>
                        {pos ? "+" : "−"}{fmt(Math.abs(d.kg))}
                      </span>
                    </div>
                  );
                })}
              </div>

              <div className="at-card" style={{ marginBottom: 14 }}>
                <h3 style={{ fontSize: 17, marginBottom: 14 }}>Risk alerts</h3>
                {result.alerts.map((a, i) => {
                  const I = a.level === "low" ? CheckCircle2 : a.level === "med" ? Info : AlertTriangle;
                  return (
                    <div className={`at-alert ${a.level}`} key={i}>
                      <I size={18} style={{ flex: "none", marginTop: 1 }} />
                      <div>
                        <div className="a-t">{a.title}</div>
                        <div className="a-b">{a.body}</div>
                      </div>
                    </div>
                  );
                })}
              </div>

              <div className="at-card">
                <h3 style={{ fontSize: 17, marginBottom: 14 }}>What to do next</h3>
                {result.recs.map((r, i) => (
                  <div key={i} style={{ display: "flex", gap: 11, padding: "11px 0", borderBottom: i < result.recs.length - 1 ? "1px solid #e9ece3" : "none" }}>
                    <span style={{ width: 30, height: 30, borderRadius: 9, background: "#e4f0dc", color: "var(--leaf)", display: "grid", placeItems: "center", flex: "none" }}>
                      <r.icon size={15} />
                    </span>
                    <div>
                      <div style={{ fontWeight: 700, fontSize: 14.5, marginBottom: 2 }}>{r.t}</div>
                      <div className="at-sub" style={{ fontSize: 13.5 }}>{r.b}</div>
                    </div>
                  </div>
                ))}
              </div>
            </>
          )}
        </div>
      </div>

      <div className="at-note" style={{ marginTop: 20 }}>
        <Info size={17} style={{ flex: "none" }} />
        <span>
          The estimate comes from a transparent rule-based model built for this demo, not a trained
          Random Forest or XGBoost regressor. Swap <code>predictYield()</code> for a call to your fitted
          model and the rest of the screen keeps working — the driver bars read like a SHAP plot by design.
        </span>
      </div>
    </section>
  );
}

const ExtraStyles = () => (
  <style>{`
@keyframes at-spin{to{transform:rotate(360deg)}}
.at-split{grid-template-columns:minmax(0,1fr) minmax(0,1.25fr)}
@media (max-width:900px){ .at-split{grid-template-columns:1fr} }
.at-root code{background:#dfe6d5;padding:1px 5px;border-radius:5px;font-size:12.5px}
.at-pill{display:inline-flex;align-items:center;gap:6px;padding:7px 12px;border-radius:99px;border:1px solid var(--line);
  background:#fbfcf9;font:inherit;font-size:13.5px;font-weight:600;cursor:pointer;color:var(--field)}
.at-pill[aria-pressed="true"]{background:var(--leaf);border-color:var(--leaf);color:#fff}
`}</style>
);

/* ----------------------------- Trends ----------------------------- */

const LINE_COLORS = ["#2f6b3f", "#a8683a", "#7fb069", "#c08a1e", "#4e7f8c", "#8a5a7a"];

function Trends({ data }) {
  const [mode, setMode] = useState("crops");
  const [picked, setPicked] = useState(["rice", "wheat", "maize"]);
  const [pickedStates, setPickedStates] = useState(["Punjab", "Bihar", "Tamil Nadu"]);
  const [stateCrop, setStateCrop] = useState("rice");

  const toggle = (list, setList, v, max = 6) =>
    setList(list.includes(v) ? list.filter((x) => x !== v) : list.length >= max ? list : [...list, v]);

  const cropChart = useMemo(
    () => data.ny.map((y, i) => {
      const row = { year: y };
      picked.forEach((c) => { row[c] = data.national[c].yield[i]; });
      return row;
    }),
    [picked, data]
  );

  const stateChart = useMemo(
    () => data.sy.map((y, i) => {
      const row = { year: y };
      pickedStates.forEach((s) => { row[s] = data.stateSeries[s]?.[stateCrop]?.yield[i] ?? null; });
      return row;
    }),
    [pickedStates, stateCrop, data]
  );

  const active = mode === "crops" ? picked : pickedStates;
  const chartData = mode === "crops" ? cropChart : stateChart;
  const growthRows = active.map((k, i) => {
    const arr = mode === "crops" ? data.national[k].yield : data.stateSeries[k]?.[stateCrop]?.yield || [];
    const g = cagr(arr);
    const first = arr.filter(Boolean)[0];
    const last = lastVal(arr);
    return { key: k, label: mode === "crops" ? cropLabel(k) : k, color: LINE_COLORS[i % LINE_COLORS.length], g, first, last };
  });

  return (
    <section className="at-section at-wrap">
      <div className="at-hd">
        <div>
          <h2 style={{ fontSize: 30 }}>Fifty years of yield</h2>
          <p className="at-sub" style={{ marginTop: 8, maxWidth: "60ch" }}>
            Compare crops across the country, or the same crop across states. Pick up to six lines.
          </p>
        </div>
        <div style={{ display: "flex", gap: 8 }}>
          <button className="at-pill" aria-pressed={mode === "crops"} onClick={() => setMode("crops")}>
            <Wheat size={15} /> By crop
          </button>
          <button className="at-pill" aria-pressed={mode === "states"} onClick={() => setMode("states")}>
            <MapPin size={15} /> By state
          </button>
        </div>
      </div>

      <div className="at-card" style={{ marginBottom: 16 }}>
        {mode === "crops" ? (
          <div style={{ display: "flex", flexWrap: "wrap", gap: 8 }}>
            {data.crops.map((c) => (
              <button key={c} className="at-pill" aria-pressed={picked.includes(c)} onClick={() => toggle(picked, setPicked, c)}>
                {CROP_META[c]?.emoji} {cropLabel(c)}
              </button>
            ))}
          </div>
        ) : (
          <>
            <div style={{ maxWidth: 320, marginBottom: 14 }}>
              <label className="at-lab" htmlFor="t-crop">Crop to compare</label>
              <select id="t-crop" className="at-sel" value={stateCrop} onChange={(e) => setStateCrop(e.target.value)}>
                {data.crops.map((c) => <option key={c} value={c}>{cropLabel(c)}</option>)}
              </select>
            </div>
            <div style={{ display: "flex", flexWrap: "wrap", gap: 8 }}>
              {data.states.filter((s) => data.stateSeries[s]?.[stateCrop]).map((s) => (
                <button key={s} className="at-pill" aria-pressed={pickedStates.includes(s)} onClick={() => toggle(pickedStates, setPickedStates, s)}>
                  {s}
                </button>
              ))}
            </div>
          </>
        )}
      </div>

      {active.length === 0 ? (
        <div className="at-note">
          <Info size={17} style={{ flex: "none" }} />
          <span>Nothing selected. Choose at least one {mode === "crops" ? "crop" : "state"} above to draw the chart.</span>
        </div>
      ) : (
        <>
          <div className="at-card" style={{ marginBottom: 16 }}>
            <ResponsiveContainer width="100%" height={340}>
              <LineChart data={chartData} margin={{ top: 8, right: 10, left: -10, bottom: 0 }}>
                <CartesianGrid stroke="#e4e9dc" vertical={false} />
                <XAxis dataKey="year" {...chartAxis} minTickGap={28} />
                <YAxis {...chartAxis} width={58} label={{ value: "kg/ha", angle: -90, position: "insideLeft", fill: "#5d6b58", fontSize: 12 }} />
                <Tooltip {...tipStyle} formatter={(v, n) => [`${fmt(v)} kg/ha`, mode === "crops" ? cropLabel(n) : n]} />
                <Legend wrapperStyle={{ fontSize: 13 }} formatter={(v) => (mode === "crops" ? cropLabel(v) : v)} />
                {active.map((k, i) => (
                  <Line key={k} type="monotone" dataKey={k} stroke={LINE_COLORS[i % LINE_COLORS.length]} strokeWidth={2.2} dot={false} connectNulls />
                ))}
              </LineChart>
            </ResponsiveContainer>
          </div>

          <div className="at-card">
            <h3 style={{ fontSize: 18, marginBottom: 4 }}>Growth behind each line</h3>
            <p className="at-sub" style={{ marginBottom: 14 }}>
              Compounded annual growth between the first and last year on record.
            </p>
            <div className="at-scroll">
              <table className="at-tbl">
                <thead>
                  <tr><th></th><th>{mode === "crops" ? "Crop" : "State"}</th><th>First year</th><th>Latest</th><th>Multiple</th><th>Annual growth</th></tr>
                </thead>
                <tbody>
                  {growthRows.map((r) => (
                    <tr key={r.key}>
                      <td style={{ width: 22 }}><span style={{ display: "block", width: 11, height: 11, borderRadius: 3, background: r.color }} /></td>
                      <td style={{ fontWeight: 600 }}>{r.label}</td>
                      <td>{fmt(r.first)}</td>
                      <td>{fmt(r.last)}</td>
                      <td>{r.first && r.last ? `${(r.last / r.first).toFixed(1)}×` : "—"}</td>
                      <td>
                        {r.g === null ? "—" : (
                          <span className={`at-chip ${r.g > 0.3 ? "up" : r.g < -0.3 ? "down" : "flat"}`}>
                            {r.g > 0 ? "+" : ""}{r.g.toFixed(2)}% a year
                          </span>
                        )}
                      </td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>
          </div>
        </>
      )}
    </section>
  );
}

/* ----------------------------- Reports ---------------------------- */

function Reports({ data }) {
  const [crop, setCrop] = useState("rice");
  const [scope, setScope] = useState("All states");
  const [query, setQuery] = useState("");
  const [sortKey, setSortKey] = useState("yield");

  const rows = useMemo(() => {
    const out = data.districts
      .filter((d) => d.c[crop])
      .filter((d) => scope === "All states" || d.s === scope)
      .filter((d) => !query || d.d.toLowerCase().includes(query.toLowerCase()) || d.s.toLowerCase().includes(query.toLowerCase()))
      .map((d) => {
        const [area, y, mean] = d.c[crop];
        return {
          district: d.d, state: d.s, year: d.y, area, yield: y, mean,
          production: Math.round((area * y) / 1000),
          vsMean: mean ? ((y - mean) / mean) * 100 : null,
        };
      });
    return out.sort((a, b) =>
      sortKey === "district" ? a.district.localeCompare(b.district) : (b[sortKey] || 0) - (a[sortKey] || 0)
    );
  }, [crop, scope, query, sortKey, data]);

  const totals = useMemo(() => {
    const area = rows.reduce((s, r) => s + r.area, 0);
    const prod = rows.reduce((s, r) => s + r.production, 0);
    const best = rows.reduce((b, r) => (!b || r.yield > b.yield ? r : b), null);
    return { area, prod, avg: area ? (prod / area) * 1000 : 0, best, n: rows.length };
  }, [rows]);

  const downloadCsv = () => {
    const head = ["District", "State", "Survey year", "Area (1000 ha)", "Yield (kg/ha)", "10-yr avg yield (kg/ha)", "Est. production (1000 t)", "Vs 10-yr avg (%)"];
    const body = rows.map((r) => [r.district, r.state, r.year, r.area, r.yield, r.mean, r.production, r.vsMean === null ? "" : r.vsMean.toFixed(1)]);
    const csv = [head, ...body].map((l) => l.map((c) => `"${String(c ?? "").replace(/"/g, '""')}"`).join(",")).join("\n");
    const url = URL.createObjectURL(new Blob([csv], { type: "text/csv;charset=utf-8;" }));
    const a = document.createElement("a");
    a.href = url;
    a.download = `agritwin-${crop}-${scope.toLowerCase().replace(/\s+/g, "-")}.csv`;
    a.click();
    URL.revokeObjectURL(url);
  };

  return (
    <section className="at-section at-wrap">
      <div className="at-hd">
        <div>
          <h2 style={{ fontSize: 30 }}>Build a report</h2>
          <p className="at-sub" style={{ marginTop: 8, maxWidth: "60ch" }}>
            Filter the district records down to what you need, then take the table away as a CSV.
          </p>
        </div>
        <button className="at-btn" onClick={downloadCsv} disabled={!rows.length}>
          <Download size={17} /> Download CSV
        </button>
      </div>

      <div className="at-card" style={{ marginBottom: 16 }}>
        <div className="at-grid g4">
          <div>
            <label className="at-lab" htmlFor="r-crop">Crop</label>
            <select id="r-crop" className="at-sel" value={crop} onChange={(e) => setCrop(e.target.value)}>
              {data.crops.map((c) => <option key={c} value={c}>{CROP_META[c]?.emoji} {cropLabel(c)}</option>)}
            </select>
          </div>
          <div>
            <label className="at-lab" htmlFor="r-scope">State</label>
            <select id="r-scope" className="at-sel" value={scope} onChange={(e) => setScope(e.target.value)}>
              <option>All states</option>
              {data.states.map((s) => <option key={s}>{s}</option>)}
            </select>
          </div>
          <div>
            <label className="at-lab" htmlFor="r-sort">Sort by</label>
            <select id="r-sort" className="at-sel" value={sortKey} onChange={(e) => setSortKey(e.target.value)}>
              <option value="yield">Highest yield</option>
              <option value="production">Largest production</option>
              <option value="area">Largest area</option>
              <option value="district">District name</option>
            </select>
          </div>
          <div>
            <label className="at-lab" htmlFor="r-q">Find a district</label>
            <div style={{ position: "relative" }}>
              <Search size={15} color="var(--muted)" style={{ position: "absolute", left: 11, top: 13 }} />
              <input id="r-q" className="at-in" style={{ paddingLeft: 33 }} value={query}
                placeholder="Type a name" onChange={(e) => setQuery(e.target.value)} />
            </div>
          </div>
        </div>
      </div>

      {rows.length === 0 ? (
        <div className="at-card" style={{ textAlign: "center", padding: "48px 24px" }}>
          <Search size={26} color="var(--muted)" />
          <h3 style={{ fontSize: 19, margin: "12px 0 8px" }}>No districts match</h3>
          <p className="at-sub" style={{ maxWidth: "40ch", margin: "0 auto 16px" }}>
            {cropLabel(crop)} isn’t recorded for this filter. Widen the state to “All states” or clear the search.
          </p>
          <button className="at-btn ghost sm" onClick={() => { setScope("All states"); setQuery(""); }}>
            <RefreshCw size={15} /> Clear the filters
          </button>
        </div>
      ) : (
        <>
          <div className="at-grid g4" style={{ marginBottom: 16 }}>
            <Kpi icon={MapPin} label="Districts in report" value={fmt(totals.n)} note={scope} />
            <Kpi icon={Ruler} label="Total area" value={fmt(totals.area)} note="thousand hectares" />
            <Kpi icon={Scale} label="Estimated production" value={fmt(totals.prod)} note="thousand tonnes" />
            <Kpi icon={Wheat} label="Weighted yield" value={fmt(totals.avg)} note={`best: ${totals.best?.district || "—"}`} />
          </div>

          <div className="at-card">
            <div className="at-scroll" style={{ maxHeight: 560, overflowY: "auto" }}>
              <table className="at-tbl">
                <thead>
                  <tr>
                    <th>District</th><th>State</th><th>Year</th><th>Area</th><th>Yield</th>
                    <th>10-yr avg</th><th>Production</th><th>Vs avg</th>
                  </tr>
                </thead>
                <tbody>
                  {rows.map((r) => (
                    <tr key={`${r.state}-${r.district}`}>
                      <td style={{ fontWeight: 600 }}>{r.district}</td>
                      <td style={{ color: "var(--muted)" }}>{r.state}</td>
                      <td>{r.year}</td>
                      <td>{fmt(r.area)}</td>
                      <td style={{ fontWeight: 600 }}>{fmt(r.yield)}</td>
                      <td>{fmt(r.mean)}</td>
                      <td>{fmt(r.production)}</td>
                      <td>
                        {r.vsMean === null ? "—" : (
                          <span className={`at-chip ${r.vsMean > 3 ? "up" : r.vsMean < -3 ? "down" : "flat"}`}>
                            {r.vsMean > 0 ? "+" : ""}{r.vsMean.toFixed(0)}%
                          </span>
                        )}
                      </td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>
          </div>
        </>
      )}
    </section>
  );
}

/* ------------------------------- App ------------------------------ */

export default function App() {
  const [page, setPage] = useState("home");
  const [menuOpen, setMenuOpen] = useState(false);
  const [reloadKey, setReloadKey] = useState(0);
  const [forceError, setForceError] = useState(false);
  const { status, data, error } = useDataset(reloadKey, forceError);

  const go = (id) => { setPage(id); setMenuOpen(false); window.scrollTo({ top: 0, behavior: "smooth" }); };

  return (
    <div className="at-root">
      <Styles />
      <ExtraStyles />

      <nav className="at-nav">
        <div className="at-nav-in">
          <button className="at-brand" onClick={() => go("home")}
            style={{ background: "transparent", border: 0, color: "inherit", cursor: "pointer", padding: 0 }}>
            <span className="at-brand-mark"><Sprout size={18} /></span> AgriTwin
          </button>
          <div className="at-tabs">
            {NAV.map(({ id, label, Icon }) => (
              <button key={id} className="at-tab" aria-current={page === id ? "page" : undefined} onClick={() => go(id)}>
                <Icon size={16} /> {label}
              </button>
            ))}
          </div>
          <button className="at-burger" aria-label="Menu" aria-expanded={menuOpen} onClick={() => setMenuOpen((v) => !v)}>
            {menuOpen ? <X size={22} /> : <Menu size={22} />}
          </button>
        </div>
        <div className={`at-drawer${menuOpen ? " open" : ""}`}>
          {NAV.map(({ id, label, Icon }) => (
            <button key={id} className="at-tab" aria-current={page === id ? "page" : undefined} onClick={() => go(id)}>
              <Icon size={16} /> {label}
            </button>
          ))}
        </div>
      </nav>

      {status === "loading" && (
        <div className="at-wrap at-section">
          <Skeleton h={38} w="45%" style={{ marginBottom: 14 }} />
          <Skeleton h={16} w="70%" style={{ marginBottom: 28 }} />
          <LoadingPanel label="Reading ICRISAT-District_Level_Data.csv…" />
        </div>
      )}

      {status === "error" && (
        <div className="at-wrap at-section">
          <ErrorPanel message={error} onRetry={() => { setForceError(false); setReloadKey((k) => k + 1); }} />
        </div>
      )}

      {status === "ready" && data && (
        <main>
          {page === "home" && <Home data={data} go={go} />}
          {page === "dashboard" && <Dashboard data={data} />}
          {page === "predict" && <Predict data={data} />}
          {page === "trends" && <Trends data={data} />}
          {page === "reports" && <Reports data={data} />}
        </main>
      )}

      <footer className="at-foot">
        <div className="at-wrap" style={{ display: "flex", gap: 14, flexWrap: "wrap", alignItems: "center" }}>
          <span>
            Source: ICRISAT District Level Database, India · {fmt(RAW.meta.rows)} records, {RAW.meta.from}–{RAW.meta.to}.
          </span>
          <button className="at-btn ghost sm" style={{ marginLeft: "auto" }}
            onClick={() => { setForceError(true); setReloadKey((k) => k + 1); }}>
            <AlertTriangle size={14} /> Test the error state
          </button>
          <button className="at-btn ghost sm" onClick={() => { setForceError(false); setReloadKey((k) => k + 1); }}>
            <RefreshCw size={14} /> Reload the data
          </button>
        </div>
      </footer>
    </div>
  );
}
